import { renderResearchShelf } from './research-ui.js';
import { renderRepertoire } from './repertoire-ui.js';
import { independentHousehold } from './household-residence.js';
import { HOME_DEFINITIONS, householdHome } from './home-ownership.js';

export function renderHome(s,actions,ui) {
 const {e,button,actionCards}=ui,home=householdHome(s),def=HOME_DEFINITIONS[home.tier],here=home.locationId===s.locationId,site=s.world.locations.find(p=>p.id===home.locationId);
 const essentials=actions.filter(a=>a.id==='home_rest'||a.id==='career_work'&&s.hero.profession==='Scholar'&&here);
 const time=actions.filter(a=>a.id.startsWith('lineage_nurture_')||!independentHousehold(s)&&a.id.startsWith('family_'));
 const household=[s.hero.name,...(s.life.people||[]).filter(p=>p.id===s.life.partnerId&&p.alive!==false).map(p=>p.name),...(s.life.children||[]).filter(c=>c.alive!==false).map(c=>c.name)];
 const offers=actions.filter(a=>a.id.startsWith('life_home_'));
 const records=home.legacyCottages.filter(c=>c.locationId!==home.locationId||home.tier!=='cottage');
 const listings=offers.map(a=>`<article class="home-offer"><div><h4>${e(HOME_DEFINITIONS[a.id.slice(10)].label)}</h4><p>${a.cost} Gold · ${a.days} Days</p><small>${HOME_DEFINITIONS[a.id.slice(10)].upkeep} Gold yearly upkeep</small>${a.disabledReason?`<p class="disabled-reason">${e(a.disabledReason)}</p>`:''}</div>${button('Review '+(home.owned?'Upgrade':'Purchase'),'activity',a.id,'secondary small',!!a.disabledReason)}</article>`).join('');
 return `<section class="home-overview" aria-label="Your household home"><span class="eyebrow">${home.owned?'YOUR HOME':'A PLACE OF YOUR OWN'}</span><h3>${def?e(def.label):'Your next hearth'}</h3><p class="home-address">${home.owned?here?'Here in '+e(site?.name||s.locationId):site?'In '+e(site.name):'Your earlier home has no recorded address.':'You do not own a home yet.'}</p>${def?`<p class="small-copy">${def.upkeep} Gold yearly upkeep${!here?' · Rest is available at your home’s settlement.':''}</p>`:'<p class="small-copy">Choose one home for your household. Later, move up to a townhouse or estate.</p>'}${home.owned?`<p class="home-members small-copy">Your household: ${e(household.join(', '))}. Your parents and other relatives keep their own homes.</p>`:''}${actionCards(essentials)}${renderResearchShelf(s,actions,ui)}${renderRepertoire(s,actions,ui)}<div class="home-shortcuts">${button('Family','home-family','','ghost small')}${button('Belongings','tab','inventory','ghost small')}${home.owned&&!here&&home.locationId?button('Find Home','quest-location',home.locationId,'ghost small'):''}</div>${time.length?`<details class="home-disclosure" data-disclosure="home-household"><summary>Time with your household</summary>${actionCards(time)}</details>`:''}${offers.length?`<details class="home-disclosure" data-disclosure="home-upgrades" ${!home.owned?'open':''}><summary>${home.owned?'Upgrade your home':'Choose your first home'}</summary><p class="small-copy">${home.owned?'Only larger homes are available. An upgrade replaces your household address, not your family or belongings.':'You can own one household home.'} Review the price and move before deciding.</p>${listings}</details>`:home.tier==='estate'?'<p class="home-settled small-copy">Your estate is the largest household home. No further purchase is needed.</p>':s.age<18?'<p class="small-copy">Home purchases open at eighteen.</p>':'<p class="small-copy">Finish your current moment to review homes.</p>'}${records.length?`<details class="home-disclosure" data-disclosure="home-kept-buildings"><summary>Earlier buildings</summary><p class="small-copy">These existing cottages remain in your world with their contents and benefits. No property was sold or removed.</p>${records.map(c=>`<p>${e(s.world.locations.find(p=>p.id===c.locationId)?.name||c.locationId)} · Cottage · ${e(c.condition)}</p>`).join('')}</details>`:''}</section>`;
}
export function renderHomePurchase(q,ui) {
 if(!q)return '<h2>Review your home</h2>';
 const {e,button}=ui;
 return `<span class="eyebrow">${q.upgrading?'ONE HOME, A LARGER HEARTH':'YOUR FIRST HOME'}</span><h2>${q.upgrading?'Upgrade to':'Buy'} ${q.to==='Estate'?'an':'a'} ${e(q.to.toLowerCase())}?</h2><div class="home-move"><div><small>Current</small><strong>${e(q.from)}</strong>${q.upgrading?`<span>${e(q.fromPlace)}</span>`:''}</div><span aria-hidden="true">→</span><div><small>New home</small><strong>${e(q.to)}</strong><span>${e(q.toPlace)}</span></div></div><p><strong>${q.cost} Gold · ${q.days} Days</strong></p><p>${q.upkeep} Gold yearly upkeep. Ordinary living costs during the move are approximately ${q.livingCost} Gold, in addition to the price.</p><p>${q.upgrading?'This replaces your household home; it does not buy a second one. The full price applies, with no refund or trade-in credit.':'This becomes your one household home.'} Your family, belongings and existing built-property records are kept.</p>${q.disabledReason?`<p class="disabled-reason">${e(q.disabledReason)}</p>`:''}<div class="modal-buttons">${button(q.upgrading?'Confirm Upgrade':'Confirm Purchase','home-purchase-confirm',q.tier,'primary',!!q.disabledReason)}${button('Not Now','close-modal','','ghost')}</div>`;
}
